template.query:
mutation CreateAttributeType($identifier: String!, $name: String!, $description: String, $dataType: String!, $format: String, $constraints: JSON, $defaultValue: String) {
  createAttributeType(
    input: {
      identifier: $identifier
      name: $name
      description: $description
      dataType: $dataType
      format: $format
      constraints: $constraints
      defaultValue: $defaultValue
    }
  ) {
    success
    attributeType {
      id
      identifier
      name
      description
      dataType
      format
      constraints
      defaultValue
      createdAt
    }
    errors {
      message
      code
    }
  }
}
